-- Uitvoeren na 20260908064000_email_outbox_test_mode.sql. Alles wordt teruggedraaid.
BEGIN;CREATE TEMP TABLE eot AS SELECT gen_random_uuid() user_id;INSERT INTO auth.users(id,email,email_confirmed_at) SELECT user_id,'mail-test@example.invalid',now() FROM eot;INSERT INTO public.notifications(user_id,kind,title,body,event_key) SELECT user_id,'account','Test / Test','profile|updated','mail-test' FROM eot;DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.email_outbox WHERE recipient_email='mail-test@example.invalid' AND status='held' AND attempts=0) THEN RAISE EXCEPTION 'Testmail niet veilig vastgehouden';END IF;IF EXISTS(SELECT 1 FROM public.claim_email_outbox(10)) THEN RAISE EXCEPTION 'Testmodus gaf mail vrij voor verzending';END IF;IF has_function_privilege('authenticated','public.claim_email_outbox(integer)','EXECUTE') THEN RAISE EXCEPTION 'Browser kan mailwachtrij claimen';END IF;END $$;ROLLBACK;
